import React from "react";

interface RazorpayOptions {
    key: string;
    amount: number;
    currency: string;
    name: string;
    description?: string;
    image?: string;
    order_id: string;
    handler: (response: any) => void;
    prefill?: {
        name?: string;
        email?: string;
        contact?: string;
    };
    theme?: {
        color?: string;
    };
}

const PaymentPage = () => {
    const handlePayment = async () => {
        try {
            // Step 1: Create order via your backend
            const response = await fetch("http://localhost:5000/create-order", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify({ amount: 210000 }), // Amount in paise (₹2100.00)
            });

            const order = await response.json();

            // Step 2: Initialize Razorpay options
            const options: RazorpayOptions = {
                key: "YOUR_RAZORPAY_KEY_ID", // Replace with your Razorpay Key ID
                amount: order.amount,
                currency: "INR",
                name: "Fresh Mart Supermarket",
                description: "Thank you for shopping with us!",
                image: "https://example.com/logo.png", // Optional
                order_id: order.id, // This is the order_id returned from the backend
                handler: (response) => {
                    console.log("Payment successful:", response);
                    alert(`Payment ID: ${response.razorpay_payment_id}`);
                },
                prefill: {
                    name: "John Doe",
                    email: "johndoe@example.com",
                    contact: "9876543210",
                },
                theme: {
                    color: "#3399cc",
                },
            };

            // Step 3: Create Razorpay instance and open the payment modal
            const razorpay = new window.Razorpay(options);
            razorpay.open();
        } catch (error) {
            console.error("Payment initiation failed:", error);
        }
    };

    return (
        <div>
            <h1>Fresh Mart Supermarket</h1>
            <button
                onClick={handlePayment}
                style={{
                    padding: "10px 20px",
                    backgroundColor: "#3399cc",
                    color: "#fff",
                    border: "none",
                    borderRadius: "5px",
                    cursor: "pointer",
                }}
            >
                Pay Online
            </button>
        </div>
    );
};

export default PaymentPage;
